"""tr — faith_b."""

T = {
"faith_071": ("Allah'ın «es-Selâm» isminin anlamı nedir?", ["Her türlü kusurdan uzak olan, esenlik veren", "Yaratan", "Rızık veren", "Güçlü olan"], "es-Selâm, Haşr suresinin sonunda sayılan isimlerdendir: O, her türlü noksanlıktan uzaktır."),
"faith_072": ("59:22 ayeti «O'ndan başka ilah yoktur» ifadesinin hemen ardından Allah'ın adına hangi sıfatları katar?", ["Gaybı ve şehadeti bilen, Rahman ve Rahim", "Kral ve Savaşçı", "Zengin ve Cömert", "Güçlü ve Hızlı"], "«O, kendisinden başka ilah olmayan Allah'tır; gaybı ve şehadeti bilendir. O Rahman'dır, Rahim'dir»."),
"faith_073": ("Kur'an, Allah'ın en güzel isimleriyle ne yapılmasını emreder?", ["O'na onlarla dua edilmesini", "Sadece sayılmasını", "Kapılara yazılmasını", "Susulmasını"], "«En güzel isimler Allah'ındır: O'na onlarla dua edin»."),
"faith_074": ("Tâhâ suresi Allah'ın isimlerini nasıl takdim eder?", ["«Allah! O'ndan başka ilah yoktur. En güzel isimler O'nundur»", "«İsimleri gizlidir»", "«İsimleri sayısızdır»", "«İsimleri dokuzdur»"], "«Allah! O'ndan başka ilah yoktur. En güzel isimler O'nundur»."),
"faith_075": ("Kur'an Allah'a benzerliği reddetmek için hangi ifadeyi kullanır?", ["«O'nun benzeri hiçbir şey yoktur; O işitendir, görendir»", "«O kralların en büyüğüdür»", "«O nur gibidir»", "«Kimse O'nu görmez»"], "«O'nun benzeri hiçbir şey yoktur; O işitendir, görendir»."),
"faith_076": ("Âyetü'l-Kürsî uyuklama ve uyku hakkında ne der?", ["O'nu ne uyuklama ne de uyku tutar", "Geceleri uyur", "Yedinci gün dinlenir", "Gün aşırı uyanıktır"], "«O'nu ne bir uyuklama ne de bir uyku tutar»."),
"faith_077": ("Kur'an, düşen yaprak hakkında Allah'ın bilgisi için ne der?", ["O bilmeden bir yaprak bile düşmez", "Sonradan öğrenir", "Melekler haber verir", "Yazılmaz"], "«Gaybın anahtarları O'nun katındadır… O bilmeden bir yaprak bile düşmez»."),
"faith_078": ("Kaf suresine göre Allah insana neden daha yakındır?", ["Şah damarından", "Gölgesinden", "Sesinden", "Evinden"], "«İnsanı biz yarattık ve nefsinin ona ne fısıldadığını biliriz; biz ona şah damarından daha yakınız»."),
"faith_079": ("Kur'an ateşin başındaki melekleri nasıl anlatır?", ["Allah'a isyan etmezler ve emrolunanı yaparlar", "Bazıları tereddüt eder", "Uyurlar", "Seçim yaparlar"], "«…iri gövdeli, sert melekler: Allah'ın kendilerine emrettiğine karşı gelmezler ve emrolunanı yaparlar»."),
"faith_080": ("Kur'an, Allah'ın sözü karşısında melekleri nasıl anlatır?", ["O'nun sözünün önüne geçmezler ve emriyle iş görürler", "Emirlerini tartışırlar", "Kendi başlarına karar verirler", "Hep susarlar"], "«Bilakis onlar şerefli kullardır: O'nun sözünün önüne geçmezler ve emriyle iş görürler»."),
"faith_081": ("Kur'an vahyi Peygamberin ﷺ kalbine indiren melek olarak kimi anar?", ["Cebrail", "Mikâil", "İsrafil", "Malik"], "«De ki: Kim Cebrail'e düşmansa… onu Allah'ın izniyle senin kalbine o indirmiştir»."),
"faith_082": ("Bakara suresinde Cebrail'in yanında hangi melek anılır?", ["Mikâil", "İsrafil", "Rıdvan", "Münker"], "«Kim Allah'a, meleklerine, elçilerine, Cebrail'e ve Mikâil'e düşman olursa…»"),
"faith_083": ("4:136 ayeti hangi iman esaslarını sayar?", ["Allah'ı, Elçisini, indirilen Kitabı ve önceki Kitapları", "Sadece Kitabı", "Sadece peygamberleri", "Sadece melekleri"], "«Ey iman edenler! Allah'a, Elçisine, Elçisine indirdiği Kitaba ve daha önce indirdiği Kitaba iman edin»."),
"faith_084": ("Kur'an Davud'a verildiğini bildirdiği Kitap hangisidir?", ["Zebur", "Tevrat", "İncil", "İbrahim'in sahifeleri"], "«…ve Davud'a Zebur'u verdik»."),
"faith_085": ("Kur'an'ı dinleyip iman eden cinlerin adını taşıyan sure hangisidir?", ["Cin", "İnsan", "Nâs", "Furkan"], "«De ki: Bana vahyolundu ki cinlerden bir topluluk dinledi ve şöyle dedi: Biz hayret verici bir Kur'an dinledik»."),
"faith_086": ("Zâriyât suresine göre cinler ve insanlar niçin yaratıldı?", ["Kendisine kulluk etsinler diye", "Yeryüzünü şenlendirsinler diye", "İnşa etsinler diye", "Tartışsınlar diye"], "«Ben cinleri ve insanları ancak bana kulluk etsinler diye yarattım»."),
"faith_087": ("Kur'an her nefis ve ölüm hakkında ne der?", ["Her nefis ölümü tadacaktır", "Bazı nefisler ölmez", "Ölüm bir şüphedir", "Ölüm bitmeyen bir uykudur"], "«Her nefis ölümü tadacaktır; ecirleriniz ancak kıyamet günü eksiksiz verilecektir»."),
"faith_088": ("Zilzal suresine göre insanlar amelleri kendilerine gösterilsin diye nasıl çıkacak?", ["Bölük bölük ayrılmış olarak", "Hepsi tek sırada", "Uyur hâlde", "Sessiz ve görünmez"], "«O gün insanlar amelleri kendilerine gösterilsin diye bölük bölük çıkacaklar»."),
"faith_089": ("Kehf suresi kıyamet günü amel defterini nasıl anlatır?", ["Küçük büyük hiçbir şeyi bırakmadan sayar", "Sadece büyükleri yazar", "Silinir", "İnsanlar yazar"], "«Diyecekler ki: “Vay halimize! Bu nasıl kitapmış: küçük büyük hiçbir şey bırakmadan hepsini saymış!”»"),
"faith_090": ("Kur'an kıyamet gününde uzuvlar hakkında ne der?", ["Eller konuşacak, ayaklar şahitlik edecek", "Dilsiz kalacaklar", "Gizlenecekler", "Değiştirilecekler"], "«O gün ağızlarını mühürleriz; elleri bize konuşur, ayakları da kazandıklarına şahitlik eder»."),
"faith_091": ("Kur'an namazı vakti bakımından nasıl niteler?", ["Belirli vakitlere bağlı bir farz", "Her saatte serbest", "Haftada bir", "Sadece geceleyin"], "«Şüphesiz namaz, müminler üzerine vakitleri belirlenmiş bir farzdır»."),
"faith_092": ("Ankebût suresine göre namaz neden alıkoyar?", ["Hayâsızlıktan ve kötülükten", "Açlıktan", "Hastalıktan", "Yolculuktan"], "«Namazı kıl: şüphesiz namaz hayâsızlıktan ve kötülükten alıkoyar»."),
"faith_093": ("Kur'an özellikle hangi namazı «orta namaz» diye anar?", ["Namazları koruma emri içinde adı geçer ama belirtilmez", "Sadece sabah namazını", "Sadece akşam namazını", "Cuma namazını"], "«Namazlara ve orta namaza devam edin; Allah'ın huzurunda saygıyla durun»."),
"faith_094": ("Tâhâ suresinde Kur'an namazı hangi amaçla emreder?", ["Allah'ı anmak için", "Dinlenmek için", "Toplanmak için", "Saatleri saymak için"], "«Şüphesiz ben Allah'ım: benden başka ilah yoktur. Bana kulluk et ve beni anmak için namaz kıl»."),
"faith_095": ("Mü'minûn suresinde kurtuluşa erenlerin listesi namazın hangi vasfıyla başlar?", ["Namazda huşû ile", "Uzunlukla", "Hızla", "Sayıyla"], "«Müminler gerçekten kurtuluşa ermiştir: onlar ki namazlarında huşû içindedirler»."),
"faith_096": ("İsra suresi hangi namazı «şahit olunan» (meşhûd) diye anlatır?", ["Sabah okuyuşunu", "Akşam namazını", "Öğle namazını", "Cuma namazını"], "«Güneşin batıya kaymasından gecenin karanlığına kadar namaz kıl; sabah okuyuşunu da: şüphesiz sabah okuyuşu şahit olunandır»."),
"faith_097": ("Kur'an hangi iki şeyle yardım istenmesini emreder?", ["Sabır ve namazla", "Güç ve zenginlikle", "Yolculuk ve dinlenmeyle", "Sessizlik ve yalnızlıkla"], "«Ey iman edenler! Sabır ve namazla yardım isteyin: Allah sabredenlerle beraberdir»."),
"faith_098": ("Öğle namazının farzı kaç rekâttır?", ["Dört", "İki", "Üç", "Beş"], "Öğle, ikindi ve yatsı namazlarının her biri dört rekât farzdır; mezhepler bunda ittifak etmiştir."),
"faith_099": ("Günün beş vakit farz namazının sonuncusu hangisidir?", ["Yatsı", "Sabah", "Akşam", "İkindi"], "Sıralama şöyledir: sabah, öğle, ikindi, akşam, yatsı."),
"faith_100": ("Namazdaki secde hâline ne denir?", ["Sücûd", "Rükû", "Kıyam", "Teşehhüd"], "Kıyam ayakta durmak, rükû eğilmek, sücûd secde etmek, teşehhüd ise şehadet oturuşudur."),
"faith_101": ("Kur'an Ramazan'da hasta veya yolcu için ne öngörür?", ["Başka günlerde aynı sayıda tutmayı", "Hiçbir şey", "İki kat yükümlülük", "Sürekli oruç"], "«Sizden kim hasta ya da yolculukta olursa, başka günlerde sayısınca tutsun»."),
"faith_102": ("Kur'an farz kılınan oruca hangi gayeyi verir?", ["Takvaya ulaşmayı", "Kilo vermeyi", "Tasarrufu", "Dinlenmeyi"], "«Oruç, sizden öncekilere yazıldığı gibi size de yazıldı; umulur ki takvaya erersiniz»."),
"faith_103": ("Oruç ayetlerinin ortasında Allah, yakınlığını soranlara ne cevap verir?", ["«Ben yakınım: bana dua edenin duasına karşılık veririm»", "«Geceyi bekleyin»", "«Meleklere sorun»", "«Uzakta arayın»"], "«Kullarım sana beni sorduğunda, ben yakınım: bana dua edenin duasına karşılık veririm»."),
"faith_104": ("Kur'an zekâtın kaç sınıf alıcısını sayar?", ["Sekiz", "Üç", "Beş", "On iki"], "«Sadakalar ancak fakirler, düşkünler, onda çalışanlar, kalpleri ısındırılacaklar, köleler, borçlular, Allah yolunda olanlar ve yolcular içindir»."),
"faith_105": ("Kur'an mallardan alınan zekâta hangi etkiyi nispet eder?", ["Temizler ve arttırır", "Fakirleştirir", "Semboliktir", "Namazın yerine geçer"], "«Onların mallarından, kendilerini temizleyip arındıracağın bir sadaka al»."),
"faith_106": ("Kur'an hangi iki farzı en sık birlikte anar?", ["Namaz ve zekât", "Oruç ve yolculuk", "Hac ve ticaret", "Okuma ve yazma"], "«Namazı kılın ve zekâtı verin; kendiniz için önden ne hayır gönderirseniz onu Allah katında bulursunuz»."),
"faith_107": ("Kur'an kurbanda Allah'a ulaşanın ne olduğunu söyler?", ["Ne eti ne kanı; ancak sizden gelen takva", "Sadece eti", "Sadece kanı", "Hayvan sayısı"], "«Onların ne etleri ne de kanları Allah'a ulaşır; fakat O'na sizden gelen takva ulaşır»."),
"faith_108": ("Kur'an'a göre hac için en hayırlı azık nedir?", ["Takva", "Altın", "Yiyecek", "Binek"], "«Azık edinin; şüphesiz azığın en hayırlısı takvadır»."),
"faith_109": ("Kur'an Beyt-i Atîk çevresinde hangi ibadeti anar?", ["Tavafı", "Çölde koşmayı", "Bir tepeye çıkmayı", "Orada oruç tutmayı"], "«…ve Beyt-i Atîk'i tavaf etsinler»."),
"faith_110": ("Kur'an Arafat'tan ayrıldıktan sonra Allah'ın nerede anılmasını emreder?", ["Müzdelife'de Meş'ar-i Haram'ın yanında", "Uhud dağında", "Kuba'da", "Taif'te"], "«Arafat'tan indiğinizde Meş'ar-i Haram'ın yanında Allah'ı anın»."),
"faith_111": ("Kur'an müminlerden nasıl bir tövbe ister?", ["Samimi bir tövbe (tevbe-i nasûh)", "Yazılı bir tövbe", "Alenî bir tövbe", "Yıllık bir tövbe"], "«Ey iman edenler! Samimi bir tövbe ile Allah'a dönün»."),
"faith_112": ("Şûrâ suresi tövbenin kabulü hakkında ne der?", ["Kullarının tövbesini kabul eden ve kötülükleri bağışlayan O'dur", "Tövbe kabul edilmez", "Bir aracı gerekir", "Bir yıl beklemek gerekir"], "«O, kullarından tövbeyi kabul eden, kötülükleri bağışlayan ve yaptıklarınızı bilendir»."),
"faith_113": ("Kur'an'ın övdüğü kimseler bir günah işledikten sonra ne yapar?", ["Allah'ı hatırlayıp bağışlanma dilerler", "Kaçarlar", "Susarlar", "Başkasını suçlarlar"], "«Onlar bir kötülük yaptıklarında ya da kendilerine zulmettiklerinde Allah'ı hatırlar ve günahları için bağışlanma dilerler»."),
"faith_114": ("Ahzab suresinde Kur'an Allah'ı anmayı hangi ölçüde emreder?", ["Çokça, sabah ve akşam", "Yılda bir kez", "Haftada bir kez", "Sadece yolculukta"], "«Ey iman edenler! Allah'ı çokça anın ve O'nu sabah akşam tesbih edin»."),
"faith_115": ("Âl-i İmran suresinin sonunda «akıl sahipleri» ne üzerinde düşünür?", ["Göklerin ve yerin yaratılışı üzerinde, her hâlde", "Hasat üzerinde", "Kervanlar üzerinde", "Soy kütükleri üzerinde"], "«Onlar ayakta, otururken ve yanları üzerinde Allah'ı anar, göklerin ve yerin yaratılışı üzerinde düşünürler»."),
"faith_116": ("Kur'an bir karar verildikten sonra ne yapılmasını emreder?", ["Allah'a tevekkül etmeyi", "Bir işaret beklemeyi", "Bir kâhine sormayı", "Vazgeçmeyi"], "«Kararını verdiğinde Allah'a tevekkül et: Allah tevekkül edenleri sever»."),
"faith_117": ("İnşirah suresi iş bitince arzuyu kime yöneltir?", ["Rabbine", "Dinlenmeye", "Aileye", "İnsanlara"], "«Boş kaldığında yine çalış; ve yalnız Rabbine yönel»."),
"faith_118": ("Hadid suresi dünya hayatını neye benzetir?", ["Bitkisi hoşa giden, sonra sararıp çer çöp olan bir yağmura", "Uzun bir yolculuğa", "Bir dağa", "Bir okyanusa"], "«Bilin ki dünya hayatı ancak bir oyun ve eğlencedir… bitkisi çiftçilerin hoşuna giden bir yağmur gibidir; sonra kurur, sararmış görürsün, sonra çer çöp olur»."),
"faith_119": ("Kur'an dünya süsü olan mal ve evlattan daha hayırlı olarak neyi bildirir?", ["Kalıcı salih amelleri", "Altını", "Şöhreti", "Toprakları"], "«Mal ve evlat dünya hayatının süsüdür; kalıcı salih ameller ise Rabbinin katında sevapça daha hayırlıdır»."),
"faith_120": ("Kur'an insanın yaratılış gayesi hakkında hangi soruyu sorar?", ["«Sizi boşuna yarattığımızı mı sandınız?»", "«Sizi kim adlandırdı?»", "«Nereye gideceksiniz?»", "«Kaç kişisiniz?»"], "«Sizi boşuna yarattığımızı ve bize döndürülmeyeceğinizi mi sandınız?»"),
"faith_121": ("Kur'an Allah'ı ananlara hangi vaatte bulunur?", ["«Beni anın, ben de sizi anayım»", "«Zengin olacaksınız»", "«Uzun yaşayacaksınız»", "«Yolculuk edeceksiniz»"], "«Öyleyse beni anın, ben de sizi anayım. Bana şükredin, nankörlük etmeyin»."),
"faith_122": ("Kur'an anlaşmazlıkların kime götürülmesini emreder?", ["Allah'a ve Elçisine ﷺ", "Yaşlılara", "Pazara", "Şairlere"], "«Bir konuda anlaşmazlığa düşerseniz, Allah'a ve Elçisine götürün; eğer Allah'a ve ahiret gününe inanıyorsanız»."),
"faith_123": ("Enfâl suresi Allah anıldığında müminlerin kalplerini nasıl anlatır?", ["Kalpleri titrer ve okunan ayetlerle imanları artar", "Katılaşır", "Uyuşur", "Unutur"], "«Müminler ancak o kimselerdir ki Allah anıldığında kalpleri titrer ve ayetleri okunduğunda imanları artar»."),
"faith_124": ("Kur'an neyin tamamen âlemlerin Rabbine adanmasını emreder?", ["Namazı, ibadeti, hayatı ve ölümü", "Ticareti", "Hasadı", "Yolculukları"], "«De ki: Şüphesiz namazım, ibadetim, hayatım ve ölümüm âlemlerin Rabbi olan Allah içindir»."),
"faith_125": ("Beyyine suresi emredilen ibadete hangi şartı koyar?", ["Dini yalnız Allah'a halis kılarak kulluk etmeyi", "Alenî ibadet etmeyi", "Yazılı ibadet etmeyi", "Sadece toplu ibadet etmeyi"], "«Onlara ancak dini Allah'a halis kılarak O'na kulluk etmeleri, namazı kılmaları ve zekâtı vermeleri emredilmişti»."),
"faith_126": ("Kur'an takva sahiplerine vaat edilen cennetlerde neyin aktığını anlatır?", ["Irmakların", "Yolların", "Köprülerin", "Kuyuların"], "Kur'an cennetleri tekrar tekrar «altlarından ırmaklar akan» diye anlatır."),
"faith_127": ("Kur'an müminlere ödül olarak gizlenen şey hakkında ne der?", ["Hiçbir nefis onlar için ne göz aydınlığı saklandığını bilmez", "Her şey ayrıntılı anlatılmıştır", "Servetlerdir", "Krallıklardır"], "«Yaptıklarına karşılık olarak onlar için ne göz aydınlıkları saklandığını hiç kimse bilmez»."),
"faith_128": ("Kur'an iyilik yapanlara en güzel karşılığın yanında ne vaat eder?", ["Bir ziyade (fazlalık)", "Bir erteleme", "Bir krallık", "Bir kitap"], "«İyilik yapanlara daha güzeli ve bir de fazlası vardır»."),
"faith_129": ("Kur'an takva sahiplerinin cennet kapısındaki karşılanışını nasıl anlatır?", ["«Selam size! Hoş geldiniz: ebedî kalmak üzere girin»", "Sessizce", "Uzun bir yargılamadan sonra", "Tek tek ve sözsüz"], "«Bekçileri onlara der ki: “Selam size! Hoş geldiniz: ebedî kalmak üzere girin buraya”»."),
"faith_130": ("Âl-i İmran suresinde Kur'an neye koşmayı emreder?", ["Rabbin bağışlamasına ve gökler ile yer genişliğindeki cennete", "Pazara", "Yolculuğa", "Zenginliğe"], "«Rabbinizden bir bağışlanmaya ve genişliği gökler ile yer kadar olan, takva sahipleri için hazırlanmış cennete koşun»."),
"faith_131": ("Kur'an müminin ailesine karşı hangi sorumluluğunu bildirir?", ["Kendisini ve ailesini ateşten korumayı", "Onları zengin etmeyi", "Onlara dil öğretmeyi", "Onları gezdirmeyi"], "«Ey iman edenler! Kendinizi ve ailenizi yakıtı insanlar ve taşlar olan ateşten koruyun»."),
"faith_132": ("2:177 ayeti gerçek iyiliği (birr) nasıl tanımlar?", ["Allah'a, ahiret gününe, meleklere, Kitaba ve peygamberlere iman etmek ve maldan vermek", "Yüzünü doğuya veya batıya çevirmek", "Sadece oruç tutmak", "Yolculuk etmek"], "«İyilik, yüzlerinizi doğu ve batı tarafına çevirmeniz değildir; asıl iyilik Allah'a, ahiret gününe, meleklere, Kitaba ve peygamberlere iman edendir»."),
"faith_133": ("Tevbe suresine göre yapılan amelleri kim görecek?", ["Allah, Elçisi ﷺ ve müminler", "Kimse", "Sadece melekler", "Krallar"], "«De ki: Çalışın! Allah amelinizi görecektir; Elçisi ve müminler de»."),
"faith_134": ("İhlâs suresi hangi ifadeyle biter?", ["«Hiçbir şey O'na denk değildir»", "«O en büyüktür»", "«O yakındır»", "«O ilktir»"], "«Ve hiçbir şey O'na denk değildir»."),
"faith_135": ("Hadid suresi tek bir ayette hangi dört ismi bir araya getirir?", ["Evvel, Âhir, Zâhir ve Bâtın", "Melik, Kuddûs, Selâm, Mü'min", "Hâlik, Bâri, Musavvir, Hakîm", "Hayy, Kayyûm, Semî, Basîr"], "«O Evvel'dir, Âhir'dir, Zâhir'dir, Bâtın'dır; O her şeyi bilendir»."),
"faith_136": ("Haşr suresinin sonu «el-Melik»ten sonra hangi isimleri sayar?", ["el-Kuddûs, es-Selâm, el-Mü'min, el-Müheymin", "el-Hâlik, el-Musavvir", "el-Gafûr, er-Rahîm", "es-Semî, el-Basîr"], "«O, kendisinden başka ilah olmayan Allah'tır: el-Melik, el-Kuddûs, es-Selâm, el-Mü'min, el-Müheymin, el-Azîz…»"),
"faith_137": ("«Allah'tan başka ilah yoktur, Muhammed O'nun elçisidir» sözüne ne denir?", ["Şehadet (kelime-i şehadet)", "Besmele", "Tekbir", "Tesmiye"], "Şehadet, İslam'ın ilk sözü ve ilk şartıdır."),
"faith_138": ("«Allahu ekber» sözüne ne denir?", ["Tekbir", "Tehlil", "Tesbih", "Tahmid"], "Tekbir «Allahu ekber», tesbih «sübhanallah», tahmid «elhamdülillah», tehlil ise «lâ ilâhe illallah»tır."),
"faith_139": ("«Rahman ve Rahim olan Allah'ın adıyla» sözüne ne denir?", ["Besmele", "Hamdele", "Havkale", "İstircâ"], "Besmele bir sure hariç bütün sureleri açar; havkale ise «lâ havle velâ kuvvete illâ billâh»tır."),
"faith_140": ("Kur'an bir musibet geldiğinde hangi sözü öğretir?", ["«Biz Allah'a aitiz ve O'na döneceğiz»", "«Neden ben?»", "«Geçer»", "«İnsanların kaderi bu»"], "«Onlar ki bir musibete uğradıklarında: “Biz Allah'a aitiz ve O'na döneceğiz” derler»."),
"faith_141": ("Kur'an yarın bir iş yapacağını söylerken ne denmesini emreder?", ["«Allah dilerse» (inşallah)", "«Söz verildi»", "«Mutlaka»", "«Yemin ederim»"], "«Hiçbir şey için: “Bunu yarın yapacağım” deme; ancak “Allah dilerse” de»."),
"faith_142": ("Lokman suresinin sonunda Kur'an hangi bilgiyi yalnız Allah'a ayırır?", ["Kıyamet saatini, yağmuru, rahimdekini, yarın ne kazanılacağını ve nerede ölüneceğini", "Yıldızların sayısını", "Kralların adlarını", "Günlerin sayısını"], "«Kıyamet saatinin bilgisi şüphesiz Allah katındadır; yağmuru O indirir, rahimlerde olanı O bilir. Hiç kimse yarın ne kazanacağını ve hangi yerde öleceğini bilmez»."),
"faith_143": ("Kur'an her ümmet için belirlenen ecel hakkında ne der?", ["Geldiğinde ne bir saat gecikir ne de öne alınır", "Değiştirilebilir", "Allah bilmez", "Krallara bağlıdır"], "«Her ümmetin bir eceli vardır: ecelleri geldiğinde ne bir saat geri kalırlar ne de öne geçerler»."),
"faith_144": ("Kur'an mümin olarak salih amel işleyen erkek ya da kadına ne vaat eder?", ["Güzel bir hayat ve amellerinin en güzeliyle karşılık", "Zenginlik", "İktidar", "Şöhret"], "«Erkek olsun kadın olsun, kim mümin olarak salih amel işlerse, onu güzel bir hayatla yaşatırız»."),
"faith_145": ("Hucurat suresinde Kur'an «İslam» ile «iman» arasında hangi farkı koyar?", ["«Teslim olduk» demek, imanın kalplere girmesi değildir henüz", "İkisi aynı kelimedir", "İman her zaman öncedir", "İslam sadece âlimler içindir"], "«Bedeviler: “İman ettik” dediler. De ki: “Siz iman etmediniz; fakat teslim olduk deyin: iman henüz kalplerinize girmedi”»."),
"faith_146": ("Mâide suresi bir tek insanın hayatı hakkında hangi kuralı koyar?", ["Bir kişiyi öldüren bütün insanları öldürmüş gibidir; bir kişiyi yaşatan hepsini yaşatmış gibidir", "Her can bire sayılır", "Sadece akrabalar sayılır", "Sadece sayı önemlidir"], "«Kim bir cana kıymamış ya da yeryüzünde bozgunculuk yapmamış birini öldürürse, bütün insanları öldürmüş gibidir; kim de birini yaşatırsa bütün insanları yaşatmış gibidir»."),
"faith_147": ("Kur'an iyiliğin karşılığını kaç kat artırır?", ["On kat", "İki kat", "Yüz kat", "Artırmaz"], "«Kim bir iyilik getirirse ona on katı vardır; kim de bir kötülük getirirse ancak misliyle cezalandırılır»."),
"faith_148": ("Fâtır suresi insanların Allah'la ilişkisini nasıl anlatır?", ["Onlar fakirdir, Allah ise Ganî ve Hamîd'dir", "Onlar O'nun ortaklarıdır", "Onlar müstağnidir", "Onlar O'nun alacaklısıdır"], "«Ey insanlar! Siz Allah'a muhtaç fakirlersiniz; Allah ise Ganî'dir, Hamîd'dir»."),
"faith_149": ("Asr suresine göre hangi dört haslet hüsrandan kurtarır?", ["İman, salih amel, hakkı ve sabrı tavsiye", "Zenginlik, güç, güzellik, kurnazlık", "Sessizlik, uyku, inziva, oruç", "Yolculuk, ticaret, yazı, okuma"], "«Asra andolsun! İnsan gerçekten hüsrandadır; ancak iman edip salih amel işleyenler, birbirine hakkı ve sabrı tavsiye edenler hariç»."),
"faith_150": ("Bakara suresinin sondan bir önceki ayetinde müminler neye iman ettiklerini bildirir?", ["Allah'a, meleklerine, kitaplarına ve elçilerine", "Tek bir kitaba", "Tek bir meleğe", "Atalarına"], "«Elçi, Rabbinden kendisine indirilene iman etti, müminler de: hepsi Allah'a, meleklerine, kitaplarına ve elçilerine iman etti»."),
}
